ini_set('display_errors','0');header('Content-Type: application/json;charset=utf-8');require __DIR__.'/../lib/Db.php';require __DIR__.'/../lib/Jwt.php';$C=require __DIR__.'/../config.php';$h=$_SERVER['HTTP_AUTHORIZATION']??'';if(!preg_match('/Bearer\s+(.+)/i',$h,$m)||!Jwt::verify(trim($m[1]),$C['jwt_secret'])){http_response_code(401);exit;}Db::run("CREATE TABLE IF NOT EXISTS station_sign_types(id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(190) NOT NULL,code VARCHAR(80) NULL,is_active TINYINT(1) NOT NULL DEFAULT 1,sort_order INT NOT NULL DEFAULT 0,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_sst_code(code)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");$types=[['تابلو ایستگاه تاکسی ساده','simple',1],['تابلو ایستگاه تاکسی دارای بارکرد','barcard',2],['تابلو ایستگاه تاکسی حمل با جرثقیل','crane',3],['تابلو ایستگاه دارای دوربین نظارتی پلیس','police_camera',4]];foreach($types as $t)Db::run('INSERT IGNORE INTO station_sign_types(title,code,is_active,sort_order) VALUES(?,?,1,?)',$t);echo json_encode(['ok'=>true],JSON_UNESCAPED_UNICODE);